  c = InLaneCornerTracker()
  for i in range(20):
    m, q = sample(0.)
    assert update(c, i*.05, m, [q], measurement_time_s=0.) is None


def test_moving_into_lane_requires_new_lane_dwell_not_just_old_radar_history():
  c = InLaneCornerTracker()
  for i in range(20):
    t = i*.05
    m, q = sample(t)
    if i < 10:
      m.laneLineProbs = (.9, .2, .98, .9)
    out = update(c, t, m, [q])
    if i < 17:
